#!/usr/bin/env bash
# 07-deeplink-sweep.sh <pkg> <uris-file> [--out DIR] [--user N] [--serial S] [--pin] [--warm]
#                                        [--settle S] [--dry-run] [--json] [--help]
# Fire each URI as a BROWSABLE VIEW intent -- exactly what a web page can do -- and record who handled it:
# the `am start -W` result, the ActivityManager START line (cmp=), the resumed activity and any crash.
# One line per URI; mutations are generated by tools/08-deeplink-fuzz.py (this script fires what it is given).
#
# Quoting (why): `adb shell` joins its arguments and hands ONE string to the device's /system/bin/sh -c.
# An unquoted -d "$U" is re-parsed there: `&` backgrounds and truncates the URI, `;` splits an
# intent://...#Intent;scheme=x;end into commands, `'` is an unterminated string. Every URI is therefore
# single-quoted for the REMOTE shell ('\'' escaping) and the whole remote command is one argument.
# Verified with a local `sh -c` simulator (fake adb); no device was attached when this was written.
#
# intent:// (why positional): `-d` would make the literal string the intent's data. Only
# Intent.parseUri turns it into an Intent, and `am start` does that for a trailing URI argument -- and
# honours package= AND component=. Most browsers strip component= first (see D09-008 matrix), so a hit
# through component= is a CANDIDATE that still needs the browser proof.
#
# Exit: 0 ran and >=1 CANDIDATE; 1 ran, nothing (every URI closed/other app); 2 usage/environment.
set -uo pipefail

usage() {
  sed -n '2,3p' "$0" | sed 's/^# //'
  cat <<'EOF'
  --out DIR     evidence dir (default deeplink-sweep/<pkg>): results.csv results.json logs/<n>.txt
  --user N      am start --user N (work profile / private space)
  --serial S    adb -s S (or export ANDROID_SERIAL)
  --pin         append the package to `am start` so only the target may resolve (second pass; default
                leaves resolution open so a browser/chooser win is visible)
  --warm        do not `am force-stop` the package before each URI (tests onNewIntent on a live task)
  --settle S    seconds to poll dumpsys for the resumed activity (default 4)
  --dry-run     print the exact adb commands, fire nothing
  --json        print results.json to stdout at the end
EOF
  exit "${1:-2}"
}
PKG=""; FILE=""; OUT=""; USERN=""; SERIAL="${ANDROID_SERIAL:-}"; PIN=0; WARM=0; SETTLE=4; DRY=0; JSON=0
while [ $# -gt 0 ]; do
  case "$1" in
    --out) OUT="${2:-}"; shift ;;  --user) USERN="${2:-}"; shift ;;  --serial) SERIAL="${2:-}"; shift ;;
    --pin) PIN=1 ;;  --warm) WARM=1 ;;  --settle) SETTLE="${2:-4}"; shift ;;  --dry-run) DRY=1 ;;  --json) JSON=1 ;;
    -h|--help) usage 0 ;;  -*) echo "unknown option: $1" >&2; usage ;;
    *) if [ -z "$PKG" ]; then PKG="$1"; elif [ -z "$FILE" ]; then FILE="$1"; else echo "unexpected: $1" >&2; usage; fi ;;
  esac
  shift
done
[ -z "$PKG" ] || [ -z "$FILE" ] && usage
[ -f "$FILE" ] || { echo "ERROR: no such file: $FILE" >&2; exit 2; }
case "$PKG" in *[!A-Za-z0-9._]*) echo "ERROR: package name has unexpected characters" >&2; exit 2 ;; esac
[ -z "$OUT" ] && OUT="deeplink-sweep/$PKG"
ADB=(adb); [ -n "$SERIAL" ] && ADB=(adb -s "$SERIAL")
rq() { printf "'%s'" "$(printf %s "$1" | sed "s/'/'\\\\''/g")"; }   # single-quote for the REMOTE shell
cr() { tr -d '\r'; }
USERARG=""; [ -n "$USERN" ] && USERARG="--user $USERN "
PINARG=""; [ "$PIN" = 1 ] && PINARG=" $PKG"
mkdir -p "$OUT/logs" || { echo "ERROR: cannot create $OUT" >&2; exit 2; }
CSV="$OUT/results.csv"; echo "n,uri,am_status,am_activity,resumed,start_cmp,handled_by,crash,tag,reason,log" > "$CSV"

if [ "$DRY" = 0 ]; then
  command -v adb >/dev/null 2>&1 || { echo "UNVERIFIED: adb not on PATH (see scripts/doctor.sh)"; exit 2; }
  [ "$("${ADB[@]}" get-state 2>/dev/null | cr)" = "device" ] || { echo "UNVERIFIED: no device in state 'device'"; exit 2; }
fi

# run_to <secs> <cmd...>: portable timeout (macOS has no `timeout`). Output in $TMPOUT; 124 on expiry.
TMPOUT="$OUT/logs/.am.txt"
run_to() {
  local t="$1"; shift
  "$@" > "$TMPOUT" 2>&1 & local p=$! i=0
  while kill -0 "$p" 2>/dev/null && [ "$i" -lt $((t * 10)) ]; do sleep 0.1; i=$((i + 1)); done
  if kill -0 "$p" 2>/dev/null; then kill "$p" 2>/dev/null; wait "$p" 2>/dev/null; return 124; fi
  wait "$p"
}
resumed() {  # topResumedActivity (10+), mResumedActivity (older stacks), ResumedActivity (display dump)
  "${ADB[@]}" shell dumpsys activity activities 2>/dev/null | cr \
    | grep -oE '(topResumedActivity|mResumedActivity|ResumedActivity)[=:] ?ActivityRecord\{[^ ]+ u[0-9]+ [^ }]+' \
    | head -1 | sed 's/.* u[0-9]* //'
}
BROWSERS='^(com\.android\.chrome|com\.chrome\.|org\.chromium\.|org\.mozilla\.|com\.android\.browser|com\.sec\.android\.app\.sbrowser|com\.brave\.browser|com\.opera\.|com\.microsoft\.emmx|com\.duckduckgo\.mobile|com\.kiwibrowser|com\.vivaldi\.browser|org\.bromite)'

printf '%-3s %-56s %-34s %-10s %s\n' "n" "URI" "START cmp= / resumed" "handled" "tag"
printf '%.0s-' $(seq 1 130); echo
N=0; NCAND=0
while IFS= read -r U || [ -n "$U" ]; do
  U="${U%$'\r'}"; [ -z "$U" ] && continue; case "$U" in \#*) continue ;; esac
  N=$((N + 1))
  case "$U" in
    intent:*) REMOTE="am start -W ${USERARG}-a android.intent.action.VIEW -c android.intent.category.BROWSABLE $(rq "$U")" ;;
    *)        REMOTE="am start -W ${USERARG}-a android.intent.action.VIEW -c android.intent.category.BROWSABLE -d $(rq "$U")$PINARG" ;;
  esac
  if [ "$DRY" = 1 ]; then
    [ "$WARM" = 0 ] && echo "${ADB[*]} shell am force-stop $PKG"
    echo "${ADB[*]} logcat -c"
    printf '%s shell %s\n' "${ADB[*]}" "$(rq "$REMOTE")"
    echo "${ADB[*]} shell dumpsys activity activities   # poll <= ${SETTLE}s for topResumedActivity"
    echo "${ADB[*]} logcat -d -v threadtime             # START u0 ... cmp=, FATAL EXCEPTION"
    continue
  fi
  [ "$WARM" = 0 ] && "${ADB[@]}" shell "am force-stop $(rq "$PKG")" >/dev/null 2>&1
  "${ADB[@]}" logcat -c >/dev/null 2>&1
  BEFORE="$(resumed)"
  run_to 20 "${ADB[@]}" shell "$REMOTE"; RC=$?
  AMOUT="$(cr < "$TMPOUT")"
  STATUS="$(printf '%s\n' "$AMOUT" | grep -oE '^Status: [a-z]+' | head -1 | cut -d' ' -f2)"
  ACT="$(printf '%s\n' "$AMOUT" | grep -oE '^Activity: [^ ]+' | head -1 | cut -d' ' -f2)"
  if [ "$RC" = 124 ]; then STATUS="timeout"
  elif printf '%s\n' "$AMOUT" | grep -q 'unable to resolve Intent'; then STATUS="unresolved"
  elif printf '%s\n' "$AMOUT" | grep -qE '^Error'; then STATUS="error"
  elif [ -z "$STATUS" ]; then STATUS="${STATUS:-no-output}"; fi
  # settle: poll until the resumed activity is non-empty and stable for two polls
  R=""; LAST=""; i=0
  while [ "$i" -lt $((SETTLE * 2)) ]; do
    R="$(resumed)"; [ -n "$R" ] && [ "$R" = "$LAST" ] && break; LAST="$R"; sleep 0.5; i=$((i + 1))
  done
  LOG="$OUT/logs/$N.txt"
  { printf '### %s\n### %s\n%s\n### dumpsys before=%s after=%s\n' "$U" "$REMOTE" "$AMOUT" "$BEFORE" "$R"; "${ADB[@]}" logcat -d -v threadtime 2>/dev/null | cr; } > "$LOG"
  CMP="$(grep -E '(ActivityTaskManager|ActivityManager) *: START u[0-9]+ ' "$LOG" | head -1 | grep -oE 'cmp=[^ }]+' | head -1 | cut -d= -f2)"
  CRASH="$(grep -E 'FATAL EXCEPTION|ANR in |Process [^ ]+ \(pid [0-9]+\) has died' "$LOG" | head -1 | sed 's/^.*AndroidRuntime: //;s/^.*ActivityManager: //' | cut -c1-80)"
  WHO="${CMP:-${ACT:-$R}}"; WPKG="${WHO%%/*}"
  if [ "$STATUS" = unresolved ]; then HB="none"
  elif [ "$WPKG" = "$PKG" ]; then HB="target"
  elif printf '%s' "$WHO" | grep -qE 'ChooserActivity|ResolverActivity'; then HB="chooser"
  elif printf '%s' "$WPKG" | grep -qE "$BROWSERS"; then HB="browser"
  elif [ -n "$WPKG" ]; then HB="other"; else HB="unknown"; fi
  TAG="closed"; WHY=""
  case "$STATUS" in
    timeout|no-output) TAG="UNVERIFIED"; WHY="am start gave no result (status=$STATUS); device busy or adb hung" ;;
    unresolved)        WHY="no activity matches this URI (filter mismatch)" ;;
  esac
  if [ "$TAG" = closed ]; then
    case "$HB" in
      target)
        if printf '%s' "$CRASH" | grep -q .; then TAG="CANDIDATE deeplink/crash"; WHY="$CRASH"
        elif printf '%s' "$U" | grep -qiE 'attacker\.|javascript:|file:|content:|%2e|\.\./|@|intent:'; then
          TAG="CANDIDATE deeplink/target-accepted"; WHY="routing only: confirm the sink (WebView URL / param use) with the D09/D10 hook or a screenshot"
        else TAG="INFO handled"; WHY="base link handled by $WHO"; fi ;;
      browser) WHY="handled by browser $WPKG (not the target)" ;;
      chooser) WHY="chooser shown: another app declares the same filter (D09 App Link verification)" ;;
      other)   WHY="handled by $WPKG" ;;
      none)    ;;
      *)       TAG="UNVERIFIED"; WHY="could not read START/resumed activity (dumpsys keys unknown on this build?)" ;;
    esac
  fi
  case "$TAG" in CANDIDATE*) NCAND=$((NCAND + 1)) ;; esac
  printf '%-3s %-56s %-34s %-10s %s\n' "$N" "$(printf '%s' "$U" | cut -c1-56)" "$(printf '%s' "${CMP:-$R}" | cut -c1-34)" "$HB" "$TAG"
  [ -n "$WHY" ] && printf '    %s\n' "$WHY"
  printf '%s,"%s",%s,%s,%s,%s,%s,"%s","%s","%s",%s\n' "$N" "$(printf '%s' "$U" | sed 's/"/""/g')" "$STATUS" "$ACT" "$R" "$CMP" "$HB" \
    "$(printf '%s' "$CRASH" | sed 's/"/""/g')" "$TAG" "$(printf '%s' "$WHY" | sed 's/"/""/g')" "$LOG" >> "$CSV"
done < "$FILE"

[ "$DRY" = 1 ] && { echo; echo "(dry run: nothing fired. $N URIs)"; exit 0; }
python3 - "$CSV" "$OUT/results.json" "$PKG" "$JSON" <<'PY' 2>/dev/null || true
import csv, json, sys
rows = list(csv.DictReader(open(sys.argv[1], newline="", encoding="utf-8")))
s = {"tool": "07-deeplink-sweep", "package": sys.argv[3], "probes": len(rows),
     "candidates": sum(r["tag"].startswith("CANDIDATE") for r in rows), "unverified": sum(r["tag"] == "UNVERIFIED" for r in rows),
     "rows": rows, "note": "adb (shell UID) establishes discovery only; re-prove from an HTML page (AM-02) or attacker-app/ (AM-03)"}
json.dump(s, open(sys.argv[2], "w"), indent=1)
if sys.argv[4] == "1": print(json.dumps(s, indent=1))
PY
echo
echo "[+] $N URIs, $NCAND CANDIDATE -> $OUT/results.csv  (per-URI logcat in $OUT/logs/)"
cat <<'NOTE'

MUTATE NEXT: python3 tools/08-deeplink-fuzz.py --inventory <eng>/inventory --pkg <pkg> builds the full set
  (open-redirect params, suffix/userinfo/backslash confusion, traversal, intent:// smuggling, scheme/host
  case, encoded slashes, fragment/query confusion) and fires it with this quoting.
REMINDER: adb runs as the shell UID. "target-accepted" is DISCOVERY: the deep link reached the app, not
  that the app misused it. A deep link is AM-02 (remote, one click): prove it from a real HTML page in a
  real browser (D09-008 matrix for intent://), and from attacker-app/ for AM-03, before it becomes a finding.
NOTE
[ "$NCAND" -gt 0 ] && exit 0 || exit 1
